<?php
namespace Tests\Database;
use App\Database\Seeds\CoreSeeder; use App\Services\LearningSequenceService; use CodeIgniter\Test\CIUnitTestCase; use Tests\Support\EducationFoundationFixtureTrait; use Tests\Support\IsolatedDatabaseTestTrait;
final class LearningSequenceTest extends CIUnitTestCase { use IsolatedDatabaseTestTrait, EducationFoundationFixtureTrait; protected $migrate=true; protected $namespace='App'; protected $seed=CoreSeeder::class; protected function setUp():void { parent::setUp(); $this->seedEducationFoundationFixture(); }
public function testAtpWorkflowLockAndClone():void { $tp=$this->createTestObjective(); $atp=LearningSequenceService::create(['curriculum_version_id'=>$this->versionId,'unit_id'=>$this->unitId,'subject_id'=>$this->subjectId,'grade_level_id'=>$this->gradeId,'code'=>'ATP-INF-X','name'=>'ATP Informatika X','phase'=>'E']); LearningSequenceService::addItem($atp['uuid'],$tp['uuid']); foreach(['VALIDATED','REVIEWED','APPROVED','LOCKED'] as $status) { $atp=LearningSequenceService::transition($atp['uuid'],$status,(int)$atp['revision_number']); } $clone=LearningSequenceService::clone($atp['uuid'],['code'=>'ATP-INF-X-R2']); $this->assertSame('DRAFT',$clone['workflow_status']); $this->assertSame($atp['id'],$clone['parent_sequence_id']); $this->expectException(\RuntimeException::class); LearningSequenceService::addItem($atp['uuid'],$tp['uuid']); }
public function testDuplicateObjectiveRejected():void { $tp=$this->createTestObjective(); $atp=LearningSequenceService::create(['curriculum_version_id'=>$this->versionId,'unit_id'=>$this->unitId,'subject_id'=>$this->subjectId,'grade_level_id'=>$this->gradeId,'code'=>'ATP-DUP','name'=>'ATP Dup','phase'=>'E']); LearningSequenceService::addItem($atp['uuid'],$tp['uuid']); $this->expectException(\InvalidArgumentException::class); LearningSequenceService::addItem($atp['uuid'],$tp['uuid']); }
}
